    /// <summary>
    /// Add totals/sub-totals sections.
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    private void metAddTotalsSection(CustInvoiceJour _custInvoiceJour)
    {
        // Place holder, tbd rebates.
        // Pending requirements.

        Amount totalAmount;

        void add(str _desc, Amount _amount)
        {
            salesInvoiceTmp.METIsTotalLine              = true;
            salesInvoiceTmp.METTotalLineDescription     = _desc;
            salesInvoiceTmp.METTotalLineAmount          = _amount;
            salesInvoiceTmp.insert();

            totalAmount += _amount;
        }

    }

    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_companyInfo">_companyInfo</param>
    protected void populateSalesInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, 
                                                        CompanyInfo _companyInfo)
    {
        next populateSalesInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);

        custFormLetterParameters = CustFormLetterParameters::find();

        CustTable           custTable           = _custInvoiceJour.custTable_OrderAccount();
        METCustTable        metCustTable        = METCustTable::find(custTable.AccountNum);
        BankAccountTable    eftBankAccount      = BankAccountTable::find(custFormLetterParameters.METInvoiceEFTBankAccountID);
        SalesTable          salesTable          = _custInvoiceJour.salesTable();
        METSalesTable       metSalesTable       = METSalesTable::findBySalesId(salesTable.SalesId);
        CompanyInfo         companyInfo         = CompanyInfo::find();
        METIndustryKeyTable industryKey         = METIndustryKeyTable::find(METCustTable::find(salesTable.CustAccount).IndustryKey);
        MarkupTrans         markupTransloc;
        MarkupTable         markupTableloc;
        METCustomerLicence  metCustomerLicence;
        METMetcashLicence   metMetcashLicence;
        SysDocuBrandDetails docuBrandDetails;
        SalesLine           salesLineloc;
        CustInvoiceTrans    custInvTransloc;
        DirPartyTable       dirpartyTable = custTable.DirPartyTable_FK();

        Map metChargesComponentMap = new Map(Types::String, Types::Real);
        METSalesLinePriceComponent  metSalesLinePriceComponent,metSalesLinePriceComponentloc;

        salesInvoiceHeaderFooterTmp.CompanyEmail = _companyInfo.email();
        /* Task 226482: Branding details update - Reports - Start
        // MPJ-13531
        Image img = CustTable::metGetCustReportLogo(_custInvoiceJour.InvoiceAccount);
        
        if(img)
        {
            salesInvoiceHeaderFooterTmp.companyLogo = img.getData();
        }
         End */

        salesInvoiceHeaderFooterTmp.METInvoiceReportInternetBankingNotes = custFormLetterParameters.METInvoiceReportInternetBankingNotes;
        //salesInvoiceHeaderFooterTmp.METEFTAccountDetails    = strFmt('BSB: %1 A/C: %2', eftBankAccount.BankSortCode, eftBankAccount.AccountNum);
       
        salesInvoiceHeaderFooterTmp.METEFTAccountDetails    = subStr(metCustTable.BsbReference, 1, 6);
        salesInvoiceHeaderFooterTmp.METEFTReferenceText     = subStr(metCustTable.BsbReference, strLen(metCustTable.BsbReference) - 8, 9);
        salesInvoiceHeaderFooterTmp.METStatementDate        = salesInvoiceHeaderFooterTmp.InvoiceDate;
        salesInvoiceHeaderFooterTmp.METBPayBillerCode       = metCustTable.BPayBillerCode;
        salesInvoiceHeaderFooterTmp.METBPayReference        = metCustTable.BPayReference;
        salesInvoiceHeaderFooterTmp.METDeliveryRoute        = salesTable.METRoute+' / '+ int2Str(salesTable.METRouteStopNum);//Route
        salesInvoiceHeaderFooterTmp.METCustGroup            = custTable.CustGroup;
        salesInvoiceHeaderFooterTmp.METRepCode              = metCustTable.SalesRepCode;//custTable.metGetCustomerAttribute(custTable.AccountNum, METConstants::Agentnumber);
        salesInvoiceHeaderFooterTmp.METBPayMessage          = custFormLetterParameters.METBpayMessageToCustomer;
        salesInvoiceHeaderFooterTmp.METDeliverToName        = dirpartyTable.Name;
        //salesInvoiceHeaderFooterTmp.METDeliverToAddress     = salesTable.deliveryAddress().Address;
        salesInvoiceHeaderFooterTmp.METDeliverToAddress     = custTable.metGetDeliveryaddress();
        salesInvoiceHeaderFooterTmp.METPaymTerms            = salesTable.Payment;
        salesInvoiceHeaderFooterTmp.METDueDate              = _custInvoiceJour.DueDate;
        salesInvoiceHeaderFooterTmp.METSalesOrderType       = salesTable.METSalesOrderType;
        salesInvoiceHeaderFooterTmp.METBPayMessage          = custFormLetterParameters.METBpayMessageToCustomer;
        salesInvoiceHeaderFooterTmp.METInvoiceToABN         = salesTable.VATNum;
        salesInvoiceHeaderFooterTmp.METCustOperGroupId      = custTable.METCustOperGroupId;
        salesInvoiceHeaderFooterTmp.METSpecialInstruction   = metSalesTable.DeliveryInstructions;
        salesInvoiceHeaderFooterTmp.METCustAccount          = salesTable.CustAccount;
        salesInvoiceHeaderFooterTmp.METCustName             = custTable.name();
        salesInvoiceHeaderFooterTmp.METReturnItemNum        = salesTable.ReturnItemNum;

        select firstonly LicenceNumber from metCustomerLicence
            where METCustomerLicence.CustAccount == custTable.AccountNum && metCustomerLicence.Type == METLicenceType::Tobacco;
        
        METInventItemOrderSetup metInventItemOrderSetup;
        
        custInvTransloc.clear();
        
        select firstonly RecId from custInvTransLoc
            exists join metInventItemOrderSetup
                where custInvTransLoc.InvoiceId              == _custInvoiceJour.InvoiceId
                  && custInvTransLoc.InvoiceDate             == _custInvoiceJour.InvoiceDate
                  && custInvTransLoc.SalesId                 == _custInvoiceJour.SalesId
                  && custInvTransLoc.NumberSequenceGroup     == _custInvoiceJour.NumberSequenceGroup
                  && metInventItemOrderSetup.SiteId          == salesTable.InventSiteId
                  && metInventItemOrderSetup.ItemId          == custInvTransLoc.ItemId
                  && metInventItemOrderSetup.ItemType        == METConstants::T;
         
        if (metCustomerLicence.LicenceNumber && custInvTransLoc.RecId)
        {
            salesInvoiceHeaderFooterTmp.METCustTobaccoLicense = metCustomerLicence.LicenceNumber;
        }
        
        select firstonly LicenceNumber from metMetcashLicence
            where metMetcashLicence.InventSiteId == salesTable.InventSiteId && metMetcashLicence.Type == METLicenceType::Tobacco;

        select firstonly LicenceNumber from metCustomerLicence
            where metCustomerLicence.CustAccount == custTable.AccountNum && metCustomerLicence.Type == METLicenceType::Liquor;
            
        salesInvoiceHeaderFooterTmp.METCustLiquorLicense    = metCustomerLicence.LicenceNumber;
        
        if (metMetcashLicence.LicenceNumber && custInvTransLoc.RecId)
        {
            salesInvoiceHeaderFooterTmp.METTobaccoLicense = metMetcashLicence.LicenceNumber;
        } 
        
        salesInvoiceHeaderFooterTmp.metIndustryKey          = industryKey.ParentIndustryKey; 
        salesInvoiceHeaderFooterTmp.InvoicingName           = dirpartyTable.KnownAs; 
        salesInvoiceHeaderFooterTmp.invoicingAddress        = custTable.invoiceAddress().Address;
                                                                            //reportname              //design                                              //industrykey
        docuBrandDetails = this.findByRepNameIndKeyandDesignName(METConstants::METSalesInvoice, 
                                                    this.getReportDesign(salesInvoiceHeaderFooterTmp), industryKey.IndustryKey);
        
        salesInvoiceHeaderFooterTmp.CompanyName     = industryKey.CompanyName;

        if (docuBrandDetails)
        {
            salesInvoiceHeaderFooterTmp.CompanyCoRegNum = docuBrandDetails.METTaxRegNumber;
            salesInvoiceHeaderFooterTmp.CompanyPhone    = docuBrandDetails.Phone;
            salesInvoiceHeaderFooterTmp.CompanyEmail    = docuBrandDetails.Email;
            salesInvoiceHeaderFooterTmp.METNotesFooter  = docuBrandDetails.METReportNotes;//CB272
            //salesInvoiceHeaderFooterTmp.METSupplierSiteNameAddress = docuBrandDetails.displayAddress();
        }
        
        InventLocationId locationId = SalesTable::find(salesInvoiceHeaderFooterTmp.salesId).InventLocationId;
        salesInvoiceHeaderFooterTmp.METSupplierSiteNameAddress = LogisticsPostalAddress::findByLocation(InventLocation::getLocationFromRole(InventLocation::find(locationId).RecId, LogisticsLocationRoleType::Delivery)).Address;

        METComponentCode metComponentCode;

        //getting line charges here
        while select saleslineloc
            group by metSalesLinePriceComponent.component,SalesLineloc.inventtransid
            where saleslineloc.SalesId == salesTable.SalesId
                join component from metSalesLinePriceComponent
                where METSalesLinePriceComponent.InventTransId == SalesLineloc.inventtransid
                join metComponentCode
                where metComponentCode.Component == metSalesLinePriceComponent.Component
                && metComponentCode.PriceComponent == METPriceComponent::LineCharges
        {
            select sum(value) from metSalesLinePriceComponentloc
                where metSalesLinePriceComponentloc.Component == metSalesLinePriceComponent.Component
                && metSalesLinePriceComponentloc.InventTransId == SalesLineloc.inventtransid;

            if(metChargesComponentMap.exists(metSalesLinePriceComponent.Component))
            {
                metChargesComponentMap.insert(metSalesLinePriceComponent.Component, metChargesComponentMap.lookup(metSalesLinePriceComponent.Component) + metSalesLinePriceComponentloc.Value);
            }
            else
            {
                metChargesComponentMap.insert(metSalesLinePriceComponent.Component, metSalesLinePriceComponentloc.Value);
            }
        }
        
        // DOMS totals
        MapEnumerator metMapEnumeratorStd;
        metMapEnumeratorStd = metChargesComponentMap.getEnumerator();
        while (metMapEnumeratorStd.moveNext())
        {
            salesInvoiceHeaderFooterTmp.METComponentCode        += metMapEnumeratorStd.currentKey() + '\n';
            salesInvoiceHeaderFooterTmp.METComponentVal         += strFmt('%1',metMapEnumeratorStd.currentValue()) + '\n';
            salesInvoiceHeaderFooterTmp.METComponentValueTotal  +=metMapEnumeratorStd.currentValue();
        }

        //Header Delivery and Admin fees
        select sum(Value),MarkupCategory from markupTransloc
                where markupTransloc.TransRecId    == _custInvoiceJour.recid && markupTransloc.TransTableId  == _custInvoiceJour.TableId
                && markupTransloc.IsDeleted == NoYes::No
                exists join markupTableloc
                    where markupTableloc.MarkupCode == markupTransloc.MarkupCode && markupTableloc.METChargeType == METChargeType::AdminFees;

        salesInvoiceHeaderFooterTmp.METAdminFee = markupTransloc.Value;
        // Set symbol only if admin fee than pass the $ value
        if (markupTransloc.MarkupCategory  == MarkupCategory::Fixed)
        {
            salesInvoiceHeaderFooterTmp.METAdminFeeSymbol = METConstants::Dollar;
        }
        else if (markupTransloc.MarkupCategory  == MarkupCategory::Percent)
        {
            salesInvoiceHeaderFooterTmp.METAdminFeeSymbol = METConstants::Percent;
        }
        select sum(Value) from markupTransloc
            where markupTransloc.TransRecId == _custInvoiceJour.recid && markupTransloc.TransTableId  == _custInvoiceJour.TableId
                && markupTransloc.IsDeleted == NoYes::No
                exists join markupTableloc
            where markupTableloc.MarkupCode == markupTransloc.MarkupCode && markupTableloc.METChargeType == METChargeType::DeliveryFees;

        salesInvoiceHeaderFooterTmp.METDeliveryFee = markupTransloc.Value;

        // only run for food weekly report
        TaxTrans metTaxTransStd;
        custInvoiceJour custInvoiceJourloc;
        CustInvoiceTrans custInvoiceTransloc;
           
        select sum(LineAmount),sum(LineAmountTax) from custInvoiceTransloc 
            where custInvoiceTransloc.SalesId == _custInvoiceJour.SalesId
            && custInvoiceTransloc.numberSequenceGroup == _custInvoiceJour.numberSequenceGroup
            && custInvoiceTransloc.InvoiceId == _custInvoiceJour.InvoiceId
            && custInvoiceTransloc.InvoiceDate == _custInvoiceJour.InvoiceDate && custInvoiceTransloc.TaxItemGroup == METConstants::GSTFree;

        salesInvoiceHeaderFooterTmp.metGSTFree = custInvoiceTransloc.LineAmount + custInvoiceTransloc.LineAmountTax;
        //bug 285404 end
        salesInvoiceHeaderFooterTmp.METRemittanceEmail      = this.getRemitEmail();

        this.metgetSalesOrderPriceComponent(salesInvoiceHeaderFooterTmp, _custInvoiceJour);
        
        // for CT report
        METCBCTInvoiceHeaderTable   metCBCTInvoiceHeaderTable;
        if (CompanyInfo::find().METLegalEntityType == METLegalEntityType::Liquor)
        {
            select firstonly metCBCTInvoiceHeaderTable
            where metCBCTInvoiceHeaderTable.RefSalesId == _custInvoiceJour.SalesId;

            salesInvoiceHeaderFooterTmp.METSupplierInvoiceDate  = metCBCTInvoiceHeaderTable.DocumentDate; //supplier inv date
            salesInvoiceHeaderFooterTmp.METSupplierInvoice      = metCBCTInvoiceHeaderTable.TaxInvoiceNum;// supplier inv no
            salesInvoiceHeaderFooterTmp.METSupplierName         = metCBCTInvoiceHeaderTable.getVendName(); //suplier name
            salesInvoiceHeaderFooterTmp.METVendorAccount        = metCBCTInvoiceHeaderTable.VendorAccount; //suplier Id
            salesInvoiceHeaderFooterTmp.METDeliverToAddress     = salesTable.deliveryAddress().Address; //For ALMCT invoice
        }

        //Update Charge through invoice details
        if (this.getReportDesign(salesInvoiceHeaderFooterTmp) == METConstants::FoodCTInvoice)
        {
            delete_from metSalesCTInvoiceTmp
                where metSalesCTInvoiceTmp.CreatedTransactionId == this.parmCreatedTransactionId();

            this.insertMETCTSalesInvoiceTmp(_custInvoiceJour);
        }

        if (salesTable.checkForChargeThroughClaims())
        {
            salesInvoiceHeaderFooterTmp.METIsReturnOrder = NoYes::Yes;
        }
    }

    /// <summary>
    /// Get email address of company for remit email
    /// </summary>
    /// <returns>LogisticsElectronicAddressLocator</returns>
    public LogisticsElectronicAddressLocator getRemitEmail()
    {
        LogisticsElectronicAddress logisticsElectronicAddress;
        DirPartyLocation dirPartyLocation;
        Dirpartytable dirpartytable;

        select firstonly dirpartytable
            join dirPartyLocation
                where dirPartyLocation.party == dirpartytable.recid && dirpartytable.recid == companyInfo::find().RecId
            join logisticsElectronicAddress
                where logisticsElectronicAddress.location == dirPartyLocation.location && logisticsElectronicAddress.Description == METConstants::Remitemail;

        return logisticsElectronicAddress.locator;
    }

    /// <summary>
    /// findByRepNameIndKeyandDesignName
    /// </summary>
    /// <param name = "_repName">_repName</param>
    /// <param name = "_designName">_designName</param>
    /// <param name = "_indKey">_indKey</param>
    /// <returns>SysDocuBrandDetails</returns>
    public SysDocuBrandDetails findByRepNameIndKeyandDesignName(SrsReportName _repName, SRSReportDesignName _designName, METIndustryKey _indKey)
    {
        SysDocuBrandDetails sysDocuBrandDetails;

        if (_repName && _designName && _indKey)
        {
            select firstonly sysDocuBrandDetails
                where sysDocuBrandDetails.ReportName == _repName
                && sysDocuBrandDetails.DesignName == _designName
                && sysDocuBrandDetails.METIndustryKey == _indKey;
        }
        else 
        {
            select firstonly sysDocuBrandDetails
                where sysDocuBrandDetails.ReportName == _repName
                && sysDocuBrandDetails.DesignName == METIndustryKeyTable::find(_indKey).ParentIndustryKey
                && sysDocuBrandDetails.METIndustryKey == _indKey;
        }
        return sysDocuBrandDetails;
    }

public SRSReportDesignName getReportDesign(SalesInvoiceHeaderFooterTmp _salesInvoiceHeaderFooterTmp)
{
    return METSalesOrderTypes::find(_salesInvoiceHeaderFooterTmp.METSalesOrderType).SalesInvoiceReportDesignName;
}

    /// <summary>
    /// Get sales order line charges 
    /// </summary>
    /// <param name = "_salesInvoiceHeaderFooterTmp">_salesInvoiceHeaderFooterTmp</param>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <returns>salesInvoiceHeaderFooterTmp</returns>
    public salesInvoiceHeaderFooterTmp metgetSalesOrderPriceComponent(salesInvoiceHeaderFooterTmp _salesInvoiceHeaderFooterTmp, CustInvoiceJour _custInvoiceJour)
    {
        METComponentCode metComponentCode;
        METSalesLinePriceComponent  metSalesLinePriceComponent;
        CustInvoiceTrans custInvoiceTrans,custInvoiceTransloc;
        CustInvoiceJour custInvoiceJour;
        
        // Creating a map to store and group the calculated values by component name
        Map componentTotalMap = new Map(Types::String, Types::Real);
        MapEnumerator mapEnum;
        str currentComponent;
        real calculatedLineTotal;
        real currentMapTotal;
        boolean ismdfcalculated;

        // charges eg service fee is calculated here
        while select sum(Value) from metSalesLinePriceComponent
            group by Component,custInvoiceTrans.InventTransId
                where metSalesLinePriceComponent.Value != 0
            join metComponentCode
                where metSalesLinePriceComponent.Component == metComponentCode.Component && metComponentCode.PriceComponent == METPriceComponent::LineCharges
            join custInvoiceTrans
                where metSalesLinePriceComponent.InventTransId == custInvoiceTrans.InventTransId
                    && custInvoiceTrans.InvoiceId == _custInvoiceJour.InvoiceId
        {
            // Initialized to 0 to prevent previous loop values from carrying over
            real mdfvalue = 0;

            select firstonly Qty from custInvoiceTransloc
                where custInvoiceTransloc.InventTransId == custInvoiceTrans.InventTransId;
                
            if (metSalesLinePriceComponent.Component == METConstants::DeliveryFee && !ismdfcalculated) // for delivery add mdf value
            {
                markupTrans markupTrans;
                ismdfcalculated = true;

                select firstonly CalculatedAmount from markupTrans
                where markupTrans.TransTableId      == _custInvoiceJour.TableId
                   && markupTrans.TransRecId        == _custInvoiceJour.RecId
                   && markupTrans.CalculatedAmount  != 0
                    && markupTrans.MarkupCode        == METConstants::MDF;

                if (markupTrans.RecId)  // only if MDF record actually found
                {
                    mdfValue = markupTrans.CalculatedAmount;
                }
            }
             
            // Calculate the total for this specific line iteration
            currentComponent = metSalesLinePriceComponent.Component;
            calculatedLineTotal = ((metSalesLinePriceComponent.value * custInvoiceTransloc.Qty) + mdfvalue);

            // Aggregate into the Map (If it exists, add to it. If not, insert it.)
            if (componentTotalMap.exists(currentComponent))
            {
                currentMapTotal = componentTotalMap.lookup(currentComponent);
                componentTotalMap.insert(currentComponent, currentMapTotal + calculatedLineTotal);
            }
            else
            {
                componentTotalMap.insert(currentComponent, calculatedLineTotal);
            }
            
            _salesInvoiceHeaderFooterTmp.METHeaderLineChargesTotal += metSalesLinePriceComponent.value * custInvoiceTransloc.Qty;
        }

        // Loop through the map after the while select finishes to build the final string
        mapEnum = componentTotalMap.getEnumerator();
        while (mapEnum.moveNext())
        {
            _salesInvoiceHeaderFooterTmp.METHeaderLineChargesCode  += mapEnum.currentKey() + '\n';
            _salesInvoiceHeaderFooterTmp.METHeaderLineChargesValue += strFmt('%1', mapEnum.currentValue()) + '\n';
        }
        return _salesInvoiceHeaderFooterTmp;
    }

    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
    /// <param name = "_taxSpec">_taxSpec</param>
    /// <param name = "_custPaymSchedLine">_custPaymSchedLine</param>
    /// <param name = "_prepaymentCustTrans">_prepaymentCustTrans</param>
    /// <param name = "_prepaymentTaxTrans">_prepaymentTaxTrans</param>
    protected void populateSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour,
                                            CustInvoiceTrans _custInvoiceTrans,
                                            TaxSpec _taxSpec,
                                            CustPaymSchedLine _custPaymSchedLine,
                                            CustTrans _prepaymentCustTrans,
                                            TaxTrans _prepaymentTaxTrans)
    {
        next populateSalesInvoiceTmp(_custInvoiceJour,
                                    _custInvoiceTrans,
                                    _taxSpec,
                                    _custPaymSchedLine,
                                    _prepaymentCustTrans,
                                    _prepaymentTaxTrans);
        SalesLine salesLine = SalesLine::find(_custInvoiceTrans.SalesId, _custInvoiceTrans.LineNum);
        METIndustryKey parentIndustryKey = METIndustryKeyTable::find(METCustTable::find(_custInvoiceJour.salestable().CustAccount).IndustryKey).ParentIndustryKey;
        if ((parentIndustryKey == METConstants::MFG || parentIndustryKey == METConstants::CSDCustName))
        {
            if (salesLine.METCWActualWeight > 0)
            {
                salesInvoiceTmp.qty = _custInvoiceTrans.PdsCWQty;
                
            }
            if (salesLine.METCWActualWeight == 0)
            {
                METWHSPhysDimUOMSite metWHSPhysDimUOMSite;

                select firstonly NetWeight from metWHSPhysDimUOMSite
                    where metWHSPhysDimUOMSite.ItemId == salesline.ItemId
                    && metWHSPhysDimUOMSite.UOM == salesline.SalesUnit
                    && metWHSPhysDimUOMSite.SiteId == salesline.inventDim().InventSiteId;
            
                salesInvoiceTmp.METWeight = metWHSPhysDimUOMSite.NetWeight * salesInvoiceTmp.qty;
            }
            else
            {
                salesInvoiceTmp.METWeight = salesLine.METCWActualWeight;
            }
        }
        
        if (!salesInvoiceTmp.TaxAmount)
        {
            salesInvoiceTmp.TaxAmount = _custInvoiceTrans.TaxAmount;
        }

        QueryRun tradeLoopTrans = new tradeLoopTrans(_custInvoiceTrans, tableNum(markupTrans)).buildQueryRun();
        
        salesInvoiceTmp.MCRMarkupTxt = SysLabel::labelId2String(literalStr("@SYS308474"),  _custInvoiceJour.LanguageId);
        
        while (tradeLoopTrans.next())
        {
            MarkupTrans markupTransLocal = tradeLoopTrans.get(tableNum(markupTrans));

            // Filter out ledger to Ledger.
            if (!(markupTransLocal.markuptable().CustType == MarkupType::LedgerAccount &&
                markupTransLocal.markuptable().VendType == MarkupType::LedgerAccount))
            {
                salesInvoiceTmp.MCRMarkupTxt += '\n' + markupTransLocal.MarkupCode + " = " +strFmt('%1',markupTransLocal.CalculatedAmount) ;
            }
        }

        salesInvoiceTmp.METSalesInvoiceReportLineType   = METSalesInvoiceReportLineType::Line;

        //if(_custInvoiceTrans.METCase)
        //{
        //    SalesInvoiceTmp.METCaseCost = salesInvoiceTmp.METWholesaleListPrice+(salesInvoiceTmp.METDeliveryFee+_custInvoiceTrans.lineAmountInclTax())/_custInvoiceTrans.METCase;
        //}
        salesInvoiceTmp.METCase = _custInvoiceTrans.METCase;
        
        METSalesLinePriceComponent  metSalesLinePriceComponentloc;
        
        select sum(value) from metSalesLinePriceComponentloc
            where metSalesLinePriceComponentloc.Component == METConstants::DeliveryFee && metSalesLinePriceComponentloc.InventTransId == salesLine.inventtransid;

        salesInvoiceTmp.METDeliveryFee          =   metSalesLinePriceComponentloc.Value;
        salesInvoiceTmp.METDeliveryFeeExt       =   metSalesLinePriceComponentloc.Value * _custInvoiceTrans.Qty;
        salesInvoiceTmp.METLineNum              =   _custInvoiceTrans.LineNum;
        salesInvoiceTmp.METUnitPriceExclTax     =   _custInvoiceTrans.SalesPrice;
        salesInvoiceTmp.METUnitPriceInclTax     =   _custInvoiceTrans.Qty ? (_custInvoiceTrans.lineAmountInclTax() / _custInvoiceTrans.Qty) : 0;
        salesInvoiceTmp.METOrderedQty           =   salesLine.SalesQty;
        salesInvoiceTmp.METUnitTax              =   _custInvoiceTrans.Qty ? (_custInvoiceTrans.TaxAmount / _custInvoiceTrans.Qty) : 0;
        salesInvoiceTmp.METMarginAmount         =   1;
        salesInvoiceTmp.METStandardCost         =   1;
        salesInvoiceTmp.METUnitTax              =   _custInvoiceTrans.Qty ? (_custInvoiceTrans.TaxAmount / _custInvoiceTrans.Qty) : 0;
        salesInvoiceTmp.METProductType          =   METItemType::find(_custInvoiceTrans.METItemType).Description;
        salesInvoiceTmp.METSRP                  =   salesInvoiceTmp.LineAmount;
        salesInvoiceTmp.METCAT                  =   this.metGetProductAttributeforInvCategory(_custInvoiceTrans.ItemId);

        //salesInvoiceTmp.METSuppliedQty          =   _custInvoiceTrans.Qty;
        //salesInvoiceTmp.METWeight               =   _custInvoiceTrans.METGrossWeight;// cb272 METWHSPhysDimUOMSite::convertWeight(_custInvoiceTrans.ItemId, _custInvoiceTrans.Qty, _custInvoiceTrans.SalesUnit, _custInvoiceTrans.inventDim());
        
        if(!salesInvoiceTmp.TaxAmount)
        {
            salesInvoiceTmp.METTaxExemptAmount = salesInvoiceTmp.LineAmount;
        }
       
        // For ALM Direct invoice
        //METCBCTInvoiceHeaderTable metCBCTInvoiceHeaderTable;
        //select sum(VendInvoiceAmtInclGST), sum(VendInvoiceGSTAmount)  from metCBCTInvoiceHeaderTable
        //    where metCBCTInvoiceHeaderTable.RefSalesId == _custInvoiceTrans.salesid;

        //salesInvoiceTmp.METSupplierInvoiceAmtInclGST    = metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST;
        //salesInvoiceTmp.METSupplierInvoiceGST           = metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;

        METInventTable  metInventTable = METInventTable::find(_custInvoiceTrans.ItemId);
        
        salesInvoiceTmp.METAlcoholContent   = metInventTable.AlcoholContent;
        salesInvoiceTmp.METCountryCode      = metInventTable.CountryCode;
        salesInvoiceTmp.METGTIN             = salesLine.BarCode;

        // Bug 418899 start - added for all reports if required
        METWHSPhysDimUOMSite metWHSPhysDimUOMSite;

        select firstonly NetWeight from metWHSPhysDimUOMSite
                    where metWHSPhysDimUOMSite.ItemId == salesline.ItemId
                    && metWHSPhysDimUOMSite.UOM == salesline.SalesUnit
                    && metWHSPhysDimUOMSite.SiteId == salesline.inventDim().InventSiteId;
            
        salesInvoiceTmp.metNetWeight = metWHSPhysDimUOMSite.NetWeight * salesInvoiceTmp.qty;
        //Bug 418899 end 

        // === Bug 351188 - ALM invoice picked cases / broken cases logic ===
        SRSReportDesignName reportDesignName = METSalesOrderTypes::find(_custInvoiceJour.salesTable().METSalesOrderType).SalesInvoiceReportDesignName;

        boolean isALMReport = (reportDesignName == METConstants::ALM || reportDesignName == METConstants::ALMExportSalesInvoice);

        METLegalEntityType metLegalEntityType = CompanyInfo::find().METLegalEntityType;
        if (metLegalEntityType == METLegalEntityType::Liquor && isALMReport)
        {
            METSalesInvoiceDPContext context = METSalesInvoiceDPContext::construct();
            context.custInvoiceTrans = _custInvoiceTrans;
            context.salesLine = salesLine;
        }
       
    }

