private container getProductCategory(VendAccount _vendorAccount)
{
    METVendTable metVendTable;
    InventTable inventTable;
    
    select firstonly DefaultDimension from inventTable
        exists join metVendTable
        where metVendTable.AccountNum == _vendorAccount
        && metVendTable.ChargeThroughServiceItemId == inventTable.ItemId;
    
    return this.getDimensionDisplayValue(inventTable.DefaultDimension ,METConstants::Department);
}

    private MarkupValue getMarkupValue(RecId _CustInvoiceJourrecId, METCBCTNumber _cbtInvoiceNumber, METChargeType _ChargeType)
    {
        MarkupTrans  markupTransloc;
        MarkupTable markupTableloc;
        SalesLine salesLineLoc;
        METSalesLine metSalesLineLoc;

        CustInvoiceTrans custInvoiceTransLoc;

        select firstonly RecId, InventTransId, TableId
                from custInvoiceTransLoc
                where custInvoiceTransLoc.ParentRecId == _CustInvoiceJourrecId;

        select sum(Value) from markupTransloc
                where markupTransloc.TransRecId == custInvoiceTransLoc.RecId
                        && markupTransloc.TransTableId  == custInvoiceTransLoc.TableId
                        && markupTransloc.MarkupCategory == MarkupCategory::Percent
                    exists join markupTableloc
                        where markupTableloc.MarkupCode == markupTransloc.MarkupCode
                        && markupTableloc.METChargeType == _ChargeType
                    exists join saleslineloc
                        where saleslineloc.InventTransId == custInvoiceTransLoc.InventTransId
                    exists join metSalesLineloc
                        where metSalesLineloc.SalesLine == saleslineloc.RecId
                            && metSalesLineloc.CBTInvoiceNumber == _cbtInvoiceNumber;

        return markupTransloc.Value;
    }

    private MarkupValue getMarkupCalcAmtLine(CustInvoiceTrans _custInvoiceTrans, METChargeType _ChargeType)
    {
        MarkupTrans  markupTransloc;
        MarkupTable markupTableloc;
        SalesLine salesLineLoc;
        METSalesLine metSalesLineLoc;
        
        select sum(CalculatedAmount) from markupTransloc
                where markupTransloc.TransRecId == _custInvoiceTrans.RecId
                        && markupTransloc.TransTableId  == _custInvoiceTrans.TableId
                        && markupTransloc.MarkupCategory == MarkupCategory::Percent
                    exists join markupTableloc
                        where markupTableloc.MarkupCode == markupTransloc.MarkupCode
                            && markupTableloc.METChargeType == _ChargeType
                    exists join saleslineloc
                        where saleslineloc.InventTransId == _custInvoiceTrans.InventTransId;

        return markupTransloc.CalculatedAmount;
    }

